    // Same clipping, bitmap order and drawing order as the firmware renderer.
    public static bool[] Render(ViaUiConfiguration config, ViaUiCapabilities caps)
    {
        var c = config.Bytes; bool[] pixels = new bool[caps.Width * caps.Height];
        void Pixel(int x, int y) { if (x >= 0 && y >= 0 && x < caps.Width && y < caps.Height) pixels[y * caps.Width + x] = true; }
        void Bitmap(int offset, int width, int height, int x, int y, int scale) { for (int py = 0; py < height; py++) for (int px = 0; px < width; px++) if ((c[offset + py * ((width + 7) / 8) + px / 8] & (0x80 >> (px % 8))) != 0) for (int dy = 0; dy < scale; dy++) for (int dx = 0; dx < scale; dx++) Pixel(x + px * scale + dx, y + py * scale + dy); }
        void Text(string text, int x, int y, int scale) { foreach (char ch in text) { int glyph = (ch >= 32 && ch <= 126 ? ch : '?') - 32; for (int px = 0; px < 6; px++) for (int py = 0; py < 8; py++) if ((Font[glyph * 6 + px] & (1 << py)) != 0) for (int dy = 0; dy < scale; dy++) for (int dx = 0; dx < scale; dx++) Pixel(x + px * scale + dx, y + py * scale + dy); x += 6 * scale; } }
        for (int i = 0; i < 7; i++)
        {
            int p = 16 + i * 4; if (c[p + 3] == 0) continue; int x = c[p], y = c[p + 1], s = c[p + 2];
            switch (i)
            {
                case 0: if ((c[1] & 2) != 0) Bitmap(ViaUiConfiguration.LogoOffset, c[6], c[7], x, y, s); break;
                case 1: if ((c[1] & 1) != 0) Bitmap(ViaUiConfiguration.TitleOffset, c[4], c[5], x, y, s); else Text("Qmknrf5", x, y, s); break;
                case 2: if ((c[1] & 4) != 0) { int[] glyphs = [6, 13, 12, 17]; for (int g = 0; g < 4; g++) Bitmap(ViaUiConfiguration.FontOffset + glyphs[g] * 32, 16, 16, x + g * 16 * s, y, s); } break;
                case 3: Text("12:00", x, y, s); break;
                case 4: Text("--%", x, y, s); break;
                case 5: Text("USB", x, y, s); break;
                case 6: Text("BASE", x, y, s); break;
            }
        }
        return pixels;
    }
